"use client";

import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from "react";
import {
  Activity, AlertTriangle, Archive, Armchair, BadgePercent, BarChart3, Bell, BellRing, BriefcaseBusiness,
  Building2, CalendarDays, Check, ChevronDown, ChevronLeft, CircleDollarSign, ClipboardList, Clock3,
  Command, Copy, CreditCard, Download, Edit3, Eye, Filter, Headphones, History, Home, LayoutDashboard,
  Loader2, LockKeyhole, LogOut, Luggage, MapPin, Menu, MessageSquareText, Minus, MoreHorizontal,
  Phone, Plane, Plus, Power, QrCode, RefreshCw, RotateCcw, Save, Search, Settings, ShieldCheck,
  SlidersHorizontal, Sparkles, StickyNote, TicketCheck, Trash2, UserPlus, UserRound, UsersRound, Wallet,
  X, Zap
} from "lucide-react";

type View = "dashboard"|"orders"|"operations"|"captains"|"companies"|"promos"|"lounges"|"finance"|"reports"|"activity"|"settings";
type Priority = "normal"|"important"|"urgent";
type Booking = {
  id:number; reference:string; customer_name:string; phone:string; airline:string|null; flight_number:string;
  trip_type:string; transport:string; booking_date:string; booking_time:string; passengers:number; bags:number;
  payment_method:string; payment_status:string; total_iqd:number; promo_code:string|null; discount_iqd:number;
  status:string; created_at:string; source:"customer"|"captain"; company:string|null; lounge:string|null; carts:number|null;
  priority:Priority; internal_note:string; archived_at:string|null; updated_at:string;
};
type Captain = {id:number;username:string;name:string;company:string;phone:string;active:boolean;created_at?:string};
type Promo = {id:number;company_name:string;code:string;discount_percent:number;starts_at:string|null;expires_at:string|null;max_uses:number|null;uses_count:number;active:boolean;created_at:string};
type CompanyOverview = {name:string;captains:number;promos:number;promo_uses:number;promo_code?:string|null};
type Overview = {
  stats:{bookings_today:number;new_bookings:number;completed_today:number;passengers_today:number;revenue_today:number;archived_count:number};
  captains:{total:number;active:number}; captainList:Captain[]; promos:{total:number;active:number;uses:number};
  recent:Booking[]; companies:CompanyOverview[]; promoActivity:{reference:string;customer_name:string;promo_code:string;discount_iqd:number;created_at:string}[];
};
type ActivityRow = {id:number;reference:string;action:string;old_value:string|null;new_value:string|null;actor:string;created_at:string};
type Lounge = {id:string;name:string;active:boolean;price_iqd:number;note:string;sort_order:number};
type SystemMessage = {id:number;text:string;active:boolean;created_at:string};
type WatchItem = {id:number;kind:"phone"|"captain"|"company";value:string;note:string;active:boolean;created_at:string};
type CompanyAccount = {name:string;price_per_passenger:number;notes:string;orders:number;passengers:number;paid_iqd:number;due_iqd:number};
type Operations = {lounges:Lounge[];messages:SystemMessage[];watchlist:WatchItem[];companies:CompanyAccount[];monitor:{new_orders:number;delayed_orders:number;oldest_new:string|null;busiest_lounge:string|null;active_company:string|null}};
type Filters={search:string;status:string;source:string;company:string;lounge:string;priority:string;archive:string};

const initialFilters:Filters={search:"",status:"all",source:"all",company:"all",lounge:"all",priority:"all",archive:"active"};
const statusMap:Record<string,{label:string;dot:string;badge:string}>={
  new:{label:"جديد",dot:"bg-amber-400",badge:"bg-amber-50 text-amber-700 border-amber-100"},
  received:{label:"تم الاستلام",dot:"bg-sky-400",badge:"bg-sky-50 text-sky-700 border-sky-100"},
  in_progress:{label:"قيد التنفيذ",dot:"bg-violet-400",badge:"bg-violet-50 text-violet-700 border-violet-100"},
  completed:{label:"مكتمل",dot:"bg-emerald-400",badge:"bg-emerald-50 text-emerald-700 border-emerald-100"},
  cancelled:{label:"ملغي",dot:"bg-rose-400",badge:"bg-rose-50 text-rose-700 border-rose-100"},
};
const priorityMap:Record<Priority,{label:string;badge:string}>={
  normal:{label:"عادي",badge:"bg-slate-100 text-slate-600"},important:{label:"مهم",badge:"bg-orange-50 text-orange-700"},urgent:{label:"عاجل",badge:"bg-red-50 text-red-700"}
};
const money=(n:number)=>new Intl.NumberFormat("ar-IQ").format(Number(n||0))+" د.ع";
const compact=(n:number)=>new Intl.NumberFormat("ar-IQ",{notation:"compact",maximumFractionDigits:1}).format(Number(n||0));
const dateTime=(v:string)=>new Intl.DateTimeFormat("ar-IQ",{timeZone:"Asia/Baghdad",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"}).format(new Date(v));
const dateOnly=(v:string)=>new Intl.DateTimeFormat("ar-IQ",{timeZone:"Asia/Baghdad",year:"numeric",month:"short",day:"numeric"}).format(new Date(v));
const ageMinutes=(v:string)=>Math.max(0,Math.floor((Date.now()-new Date(v).getTime())/60000));
function ageLabel(v:string){const m=ageMinutes(v);if(m<1)return "الآن";if(m<60)return `منذ ${m} دقيقة`;const h=Math.floor(m/60);if(h<24)return `منذ ${h} ساعة`;return `منذ ${Math.floor(h/24)} يوم`}
function inputDate(v:string|null){if(!v)return"";const d=new Date(v);if(Number.isNaN(d.getTime()))return"";const z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,16)}

const navGroups=[
  {label:"مركز التحكم",items:[
    {id:"dashboard" as View,label:"نظرة عامة",icon:LayoutDashboard},
    {id:"orders" as View,label:"إدارة الطلبات",icon:TicketCheck},
    {id:"operations" as View,label:"مراقبة التشغيل",icon:Activity},
  ]},
  {label:"الشركاء والخدمات",items:[
    {id:"captains" as View,label:"الكباتن",icon:UsersRound},
    {id:"companies" as View,label:"الشركات",icon:Building2},
    {id:"promos" as View,label:"الخصومات",icon:BadgePercent},
    {id:"lounges" as View,label:"الصالات",icon:Armchair},
  ]},
  {label:"الإدارة",items:[
    {id:"finance" as View,label:"الحسابات المالية",icon:Wallet},
    {id:"reports" as View,label:"التقارير والتحليلات",icon:BarChart3},
    {id:"activity" as View,label:"سجل النشاط",icon:History},
    {id:"settings" as View,label:"الإعدادات",icon:Settings},
  ]},
];

export default function EnterpriseAdmin(){
  const [token,setToken]=useState("");
  const [login,setLogin]=useState({username:"",password:""});
  const [view,setView]=useState<View>("dashboard");
  const [overview,setOverview]=useState<Overview|null>(null);
  const [bookings,setBookings]=useState<Booking[]>([]);
  const [activity,setActivity]=useState<ActivityRow[]>([]);
  const [operations,setOperations]=useState<Operations|null>(null);
  const [captains,setCaptains]=useState<Captain[]>([]);
  const [promos,setPromos]=useState<Promo[]>([]);
  const [selected,setSelected]=useState<Booking|null>(null);
  const [filters,setFilters]=useState<Filters>(initialFilters);
  const [showFilters,setShowFilters]=useState(false);
  const [loading,setLoading]=useState(false);
  const [message,setMessage]=useState("");
  const [sound,setSound]=useState(false);
  const [mobileNav,setMobileNav]=useState(false);
  const [commandOpen,setCommandOpen]=useState(false);
  const [createCaptainOpen,setCreateCaptainOpen]=useState(false);
  const [editingCaptain,setEditingCaptain]=useState<Captain|null>(null);
  const [captainPassword,setCaptainPassword]=useState("");
  const [captainForm,setCaptainForm]=useState({name:"",company:"",phone:"",username:"",password:""});
  const [createPromoOpen,setCreatePromoOpen]=useState(false);
  const [editingPromo,setEditingPromo]=useState<Promo|null>(null);
  const [promoForm,setPromoForm]=useState({companyName:"",code:"",discountPercent:10,maxUses:"",startsAt:"",expiresAt:""});
  const [newMessage,setNewMessage]=useState("");
  const [watchForm,setWatchForm]=useState({kind:"phone",value:"",note:""});
  const [paymentForm,setPaymentForm]=useState({companyName:"",amountIqd:"",note:""});
  const prevNew=useRef(0);

  useEffect(()=>{const saved=sessionStorage.getItem("mainAdminToken")||"";if(saved){setToken(saved);void loadAll(saved)}},[]);
  useEffect(()=>{if(!token)return;const t=setInterval(()=>void loadAll(token,true),15000);return()=>clearInterval(t)},[token,sound]);
  useEffect(()=>{const h=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();setCommandOpen(v=>!v)}if(e.key==="Escape"){setCommandOpen(false);setSelected(null)}};window.addEventListener("keydown",h);return()=>window.removeEventListener("keydown",h)},[]);

  async function api(path:string,options:RequestInit={},useToken=token){return fetch(path,{...options,headers:{"Content-Type":"application/json",...(options.headers||{}),...(useToken?{Authorization:`Bearer ${useToken}`}:{})}})}
  function beep(){try{const Ctx=window.AudioContext||(window as typeof window & {webkitAudioContext?:typeof AudioContext}).webkitAudioContext;const ctx=new Ctx!();const o=ctx.createOscillator();const g=ctx.createGain();o.frequency.value=880;g.gain.value=.045;o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.13)}catch{}}
  async function loadAll(useToken=token,silent=false){
    if(!silent)setLoading(true);if(!silent)setMessage("");
    try{
      const [ov,bk,ac,op,ca,pr]=await Promise.all([
        api("/api/admin/overview",{},useToken),api("/api/admin/bookings",{},useToken),api("/api/admin/activity",{},useToken),
        api("/api/admin/operations",{},useToken),api("/api/captain/admin/captains",{},useToken),api("/api/prmos/promos",{},useToken)
      ]);
      if([ov,bk,op,ca,pr].some(r=>r.status===401)){logout();return}
      const [ovx,bkx,acx,opx,cax,prx]=await Promise.all([ov.json(),bk.json(),ac.json(),op.json(),ca.json(),pr.json()]);
      if(!ov.ok)throw new Error(ovx.message||"تعذر تحميل مركز الإدارة");
      if(!bk.ok)throw new Error(bkx.message||"تعذر تحميل الطلبات");
      const next=Number(ovx.stats?.new_bookings||0);if(silent&&sound&&next>prevNew.current)beep();prevNew.current=next;
      setOverview(ovx);setBookings(bkx.bookings||[]);if(ac.ok)setActivity(acx.activity||[]);if(op.ok)setOperations(opx);if(ca.ok)setCaptains(cax.captains||[]);if(pr.ok)setPromos(prx.promos||[]);
    }catch(e){if(!silent)setMessage(e instanceof Error?e.message:"حدث خطأ غير متوقع")}finally{if(!silent)setLoading(false)}
  }
  async function doLogin(e:FormEvent){e.preventDefault();setLoading(true);setMessage("");try{const r=await api("/api/captain/admin/login",{method:"POST",body:JSON.stringify(login)},"");const x=await r.json();if(!r.ok){setMessage(x.message||"بيانات الدخول غير صحيحة");return}setToken(x.token);sessionStorage.setItem("mainAdminToken",x.token);await loadAll(x.token)}finally{setLoading(false)}}
  function logout(){setToken("");sessionStorage.removeItem("mainAdminToken");setOverview(null);setBookings([]);setOperations(null);setCaptains([]);setPromos([])}

  async function mutateOrder(id:number,patch:Record<string,unknown>){const r=await api("/api/admin/bookings",{method:"PATCH",body:JSON.stringify({id,...patch})});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر تحديث الطلب");return}await loadAll(token,true);setSelected(v=>v?.id===id?{...v,...("status" in patch?{status:String(patch.status)}:{}),...("priority" in patch?{priority:patch.priority as Priority}:{}),...("internalNote" in patch?{internal_note:String(patch.internalNote)}:{}),...("archived" in patch?{archived_at:patch.archived?new Date().toISOString():null}:{})}:v)}
  async function operationsAction(method:"POST"|"PATCH"|"DELETE",body?:Record<string,unknown>,query=""){const r=await api(`/api/admin/operations${query}`,{method,body:body?JSON.stringify(body):undefined});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر تنفيذ الإجراء");return false}await loadAll(token,true);return true}

  async function createCaptain(e:FormEvent){e.preventDefault();const r=await api("/api/captain/admin/captains",{method:"POST",body:JSON.stringify(captainForm)});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر إنشاء الكابتن");return}setCaptainForm({name:"",company:"",phone:"",username:"",password:""});setCreateCaptainOpen(false);await loadAll(token,true)}
  async function saveCaptain(e:FormEvent){e.preventDefault();if(!editingCaptain)return;const r=await api("/api/captain/admin/captains",{method:"PATCH",body:JSON.stringify({...editingCaptain,password:captainPassword})});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر حفظ الكابتن");return}setEditingCaptain(null);setCaptainPassword("");await loadAll(token,true)}
  async function toggleCaptain(c:Captain){const r=await api("/api/captain/admin/captains",{method:"PATCH",body:JSON.stringify({...c,active:!c.active,password:""})});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر تغيير حالة الكابتن");return}await loadAll(token,true)}
  async function deleteCaptain(c:Captain){if(!confirm(`حذف حساب ${c.name} نهائياً؟`))return;const r=await api(`/api/captain/admin/captains?id=${c.id}`,{method:"DELETE"});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر حذف الحساب");return}await loadAll(token,true)}

  async function createPromo(e:FormEvent){e.preventDefault();const r=await api("/api/prmos/promos",{method:"POST",body:JSON.stringify({...promoForm,maxUses:promoForm.maxUses?Number(promoForm.maxUses):null})});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر إنشاء رمز الخصم");return}setPromoForm({companyName:"",code:"",discountPercent:10,maxUses:"",startsAt:"",expiresAt:""});setCreatePromoOpen(false);await loadAll(token,true)}
  async function savePromo(e:FormEvent){e.preventDefault();if(!editingPromo)return;const r=await api("/api/prmos/promos",{method:"PATCH",body:JSON.stringify({id:editingPromo.id,companyName:editingPromo.company_name,code:editingPromo.code,discountPercent:editingPromo.discount_percent,startsAt:inputDate(editingPromo.starts_at),expiresAt:inputDate(editingPromo.expires_at),maxUses:editingPromo.max_uses,active:editingPromo.active})});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر حفظ الرمز");return}setEditingPromo(null);await loadAll(token,true)}
  async function togglePromo(p:Promo){const r=await api("/api/prmos/promos",{method:"PATCH",body:JSON.stringify({id:p.id,companyName:p.company_name,code:p.code,discountPercent:p.discount_percent,startsAt:inputDate(p.starts_at),expiresAt:inputDate(p.expires_at),maxUses:p.max_uses,active:!p.active})});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر تغيير حالة الرمز");return}await loadAll(token,true)}
  async function deletePromo(p:Promo){if(!confirm(`حذف رمز ${p.code}؟`))return;const r=await api(`/api/prmos/promos?id=${p.id}`,{method:"DELETE"});const x=await r.json();if(!r.ok){setMessage(x.message||"تعذر حذف الرمز");return}await loadAll(token,true)}

  const activeBookings=useMemo(()=>bookings.filter(b=>!b.archived_at),[bookings]);
  const newCount=useMemo(()=>activeBookings.filter(b=>b.status==="new").length,[activeBookings]);
  const delayed=useMemo(()=>activeBookings.filter(b=>b.status==="new"&&ageMinutes(b.created_at)>=15),[activeBookings]);
  const duplicatePhones=useMemo(()=>{const m=new Map<string,number>();activeBookings.forEach(b=>m.set(b.phone,(m.get(b.phone)||0)+1));return m},[activeBookings]);
  const companies=useMemo(()=>Array.from(new Set([...bookings.map(b=>b.company||""),...captains.map(c=>c.company),...promos.map(p=>p.company_name)].filter(Boolean))).sort(),[bookings,captains,promos]);
  const lounges=useMemo(()=>Array.from(new Set(bookings.map(b=>b.lounge).filter(Boolean) as string[])).sort(),[bookings]);
  const filtered=useMemo(()=>bookings.filter(b=>{const q=filters.search.trim().toLowerCase();const hay=[b.reference,b.customer_name,b.phone,b.company||"",b.lounge||"",b.flight_number||""].join(" ").toLowerCase();if(q&&!hay.includes(q))return false;if(filters.status!=="all"&&b.status!==filters.status)return false;if(filters.source!=="all"&&b.source!==filters.source)return false;if(filters.company!=="all"&&b.company!==filters.company)return false;if(filters.lounge!=="all"&&b.lounge!==filters.lounge)return false;if(filters.priority!=="all"&&b.priority!==filters.priority)return false;if(filters.archive==="active"&&b.archived_at)return false;if(filters.archive==="archived"&&!b.archived_at)return false;return true}),[bookings,filters]);
  const captainReport=useMemo(()=>{const m=new Map<string,{name:string;company:string;orders:number;passengers:number}>();activeBookings.filter(b=>b.source==="captain").forEach(b=>{const k=`${b.customer_name}|${b.company||""}`;const o=m.get(k)||{name:b.customer_name,company:b.company||"—",orders:0,passengers:0};o.orders++;o.passengers+=b.passengers;m.set(k,o)});return [...m.values()].sort((a,b)=>b.orders-a.orders)},[activeBookings]);
  const companyReport=useMemo(()=>{const m=new Map<string,{name:string;orders:number;passengers:number;captains:Set<string>}>();activeBookings.filter(b=>b.source==="captain"&&b.company).forEach(b=>{const n=b.company!;const o=m.get(n)||{name:n,orders:0,passengers:0,captains:new Set<string>()};o.orders++;o.passengers+=b.passengers;o.captains.add(b.customer_name);m.set(n,o)});return [...m.values()].sort((a,b)=>b.orders-a.orders)},[activeBookings]);
  const loungeReport=useMemo(()=>{const m=new Map<string,{name:string;orders:number;passengers:number}>();activeBookings.filter(b=>b.lounge).forEach(b=>{const n=b.lounge!;const o=m.get(n)||{name:n,orders:0,passengers:0};o.orders++;o.passengers+=b.passengers;m.set(n,o)});return [...m.values()].sort((a,b)=>b.passengers-a.passengers)},[activeBookings]);
  const todayKey=new Date().toLocaleDateString("en-CA",{timeZone:"Asia/Baghdad"});
  const todayOrders=useMemo(()=>activeBookings.filter(b=>new Date(b.created_at).toLocaleDateString("en-CA",{timeZone:"Asia/Baghdad"})===todayKey),[activeBookings,todayKey]);
  const financeTotal=useMemo(()=>operations?.companies.reduce((s,c)=>s+Number(c.due_iqd||0),0)||0,[operations]);
  const financePaid=useMemo(()=>operations?.companies.reduce((s,c)=>s+Number(c.paid_iqd||0),0)||0,[operations]);

  function exportCSV(){const rows=[["reference","type","name","company","lounge","phone","passengers","bags","carts","priority","status","created_at"],...filtered.map(b=>[b.reference,b.source,b.customer_name,b.company||"",b.lounge||"",b.phone,String(b.passengers),String(b.bags),String(b.carts||0),b.priority,b.status,b.created_at])];const csv="\uFEFF"+rows.map(r=>r.map(x=>`"${String(x).replace(/"/g,'""')}"`).join(",")).join("\n");const blob=new Blob([csv],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`lounge-orders-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url)}

  if(!token)return <LoginScreen login={login} setLogin={setLogin} loading={loading} message={message} submit={doLogin}/>;

  const pageTitle:Record<View,string>={dashboard:"لوحة القيادة",orders:"إدارة الطلبات",operations:"مركز العمليات",captains:"إدارة الكباتن",companies:"الشركات والشركاء",promos:"إدارة الخصومات",lounges:"إدارة الصالات",finance:"الحسابات المالية",reports:"التقارير والتحليلات",activity:"سجل النشاط",settings:"إعدادات النظام"};

  return <main dir="rtl" className="min-h-screen bg-[#f4f6f8] text-[#152f42]">
    <aside className="fixed inset-y-0 right-0 z-40 hidden w-[286px] flex-col border-l border-white/5 bg-[#0d2938] text-white lg:flex">
      <div className="border-b border-white/10 px-6 py-6"><div className="flex items-center gap-3"><div className="grid size-12 place-items-center rounded-2xl bg-[#d6ad68] text-[#12384d] shadow-lg"><Plane className="size-6 -rotate-45"/></div><div><div className="text-[10px] font-medium tracking-[.18em] text-white/45">LOUNGE BAGHDAD</div><div className="mt-1 text-lg font-semibold">Enterprise Console</div></div></div></div>
      <div className="flex-1 overflow-y-auto px-3 py-4">{navGroups.map(g=><div key={g.label} className="mb-5"><div className="px-3 pb-2 text-[10px] font-semibold tracking-wide text-white/30">{g.label}</div><div className="space-y-1">{g.items.map(item=><SidebarButton key={item.id} active={view===item.id} icon={<item.icon/>} label={item.label} badge={item.id==="orders"?newCount:0} onClick={()=>setView(item.id)}/>)}</div></div>)}</div>
      <div className="border-t border-white/10 p-4"><div className="rounded-2xl bg-white/[.055] p-3"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-[#d6ad68] text-sm font-bold text-[#12384d]">A</div><div className="min-w-0 flex-1"><div className="text-sm font-semibold">Administrator</div><div className="text-[10px] text-white/40">Full Access</div></div><button onClick={logout} className="grid size-9 place-items-center rounded-xl text-white/50 hover:bg-white/10 hover:text-white"><LogOut className="size-4"/></button></div></div></div>
    </aside>

    <div className="min-h-screen lg:mr-[286px]">
      <header className="sticky top-0 z-30 border-b border-slate-200/80 bg-white/90 backdrop-blur-xl"><div className="flex h-[74px] items-center gap-3 px-4 lg:px-7"><button onClick={()=>setMobileNav(true)} className="grid size-10 place-items-center rounded-xl border border-slate-200 lg:hidden"><Menu className="size-5"/></button><div className="min-w-0 flex-1 text-right"><div className="flex items-center justify-end gap-2 text-[10px] text-slate-400"><span>Control Center</span><ChevronLeft className="size-3"/></div><h1 className="mt-1 truncate text-lg font-bold lg:text-xl">{pageTitle[view]}</h1></div><button onClick={()=>setCommandOpen(true)} className="hidden h-10 min-w-[260px] items-center gap-3 rounded-xl border border-slate-200 bg-[#f8fafb] px-3 text-xs text-slate-400 xl:flex"><Search className="size-4"/><span className="flex-1 text-right">بحث سريع أو انتقال...</span><span dir="ltr" className="rounded-md border bg-white px-1.5 py-1 text-[9px]">⌘ K</span></button><button onClick={()=>{setSound(!sound);if(!sound)beep()}} className={`relative grid size-10 place-items-center rounded-xl border ${sound?"border-[#d6ad68] bg-[#fff8e8] text-[#9a6a20]":"border-slate-200 bg-white text-slate-500"}`}>{sound?<BellRing className="size-4.5"/>:<Bell className="size-4.5"/>}{newCount>0&&<span className="absolute -left-1 -top-1 min-w-4 rounded-full bg-red-500 px-1 text-center text-[8px] leading-4 text-white">{newCount}</span>}</button><button onClick={()=>void loadAll()} className="grid size-10 place-items-center rounded-xl border border-slate-200 bg-white text-slate-500"><RefreshCw className={`size-4.5 ${loading?"animate-spin":""}`}/></button></div></header>

      <div className="p-4 pb-24 lg:p-7 lg:pb-10">
        {message&&<div className="mb-5 flex items-center justify-between rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-sm text-red-700"><button onClick={()=>setMessage("")}><X className="size-4"/></button><span>{message}</span></div>}
        {view==="dashboard"&&<Dashboard overview={overview} newCount={newCount} delayed={delayed} todayOrders={todayOrders} operations={operations} bookings={activeBookings} captains={captains} promos={promos} loungeReport={loungeReport} companyReport={companyReport} onNavigate={setView} onOpen={setSelected}/>} 
        {view==="orders"&&<Orders bookings={filtered} total={bookings.length} filters={filters} setFilters={setFilters} companies={companies} lounges={lounges} showFilters={showFilters} setShowFilters={setShowFilters} duplicatePhones={duplicatePhones} onOpen={setSelected} onMutate={mutateOrder} onExport={exportCSV}/>} 
        {view==="operations"&&<OperationsView data={operations} delayed={delayed} newCount={newCount} messages={operations?.messages||[]} newMessage={newMessage} setNewMessage={setNewMessage} watchForm={watchForm} setWatchForm={setWatchForm} action={operationsAction}/>} 
        {view==="captains"&&<CaptainsView captains={captains} report={captainReport} onCreate={()=>setCreateCaptainOpen(true)} onEdit={setEditingCaptain} onToggle={toggleCaptain} onDelete={deleteCaptain}/>} 
        {view==="companies"&&<CompaniesView companies={operations?.companies||[]} overview={overview?.companies||[]} captains={captains} promos={promos} bookings={activeBookings} onNavigate={setView}/>} 
        {view==="promos"&&<PromosView promos={promos} onCreate={()=>setCreatePromoOpen(true)} onEdit={setEditingPromo} onToggle={togglePromo} onDelete={deletePromo}/>} 
        {view==="lounges"&&<LoungesView lounges={operations?.lounges||[]} report={loungeReport} action={operationsAction}/>} 
        {view==="finance"&&<FinanceView companies={operations?.companies||[]} total={financeTotal} paid={financePaid} paymentForm={paymentForm} setPaymentForm={setPaymentForm} action={operationsAction}/>} 
        {view==="reports"&&<ReportsView bookings={activeBookings} captainReport={captainReport} companyReport={companyReport} loungeReport={loungeReport}/>} 
        {view==="activity"&&<ActivityView rows={activity}/>} 
        {view==="settings"&&<SettingsView sound={sound} setSound={setSound} newCount={newCount}/>} 
      </div>
    </div>

    {mobileNav&&<div className="fixed inset-0 z-50 bg-black/40 lg:hidden" onClick={()=>setMobileNav(false)}><div onClick={e=>e.stopPropagation()} className="absolute inset-y-0 right-0 w-[300px] bg-[#0d2938] p-4 text-white shadow-2xl"><div className="mb-5 flex items-center justify-between"><button onClick={()=>setMobileNav(false)} className="grid size-10 place-items-center rounded-xl bg-white/10"><X className="size-5"/></button><div className="font-semibold">مركز الإدارة</div></div>{navGroups.flatMap(g=>g.items).map(item=><SidebarButton key={item.id} active={view===item.id} icon={<item.icon/>} label={item.label} badge={item.id==="orders"?newCount:0} onClick={()=>{setView(item.id);setMobileNav(false)}}/>)}</div></div>}
    <nav className="fixed inset-x-0 bottom-0 z-40 border-t border-slate-200 bg-white/95 px-2 pb-[max(8px,env(safe-area-inset-bottom))] pt-2 backdrop-blur lg:hidden"><div className="grid grid-cols-5"><MobileNav active={view==="dashboard"} icon={<Home/>} label="الرئيسية" onClick={()=>setView("dashboard")}/><MobileNav active={view==="orders"} icon={<TicketCheck/>} label="الطلبات" badge={newCount} onClick={()=>setView("orders")}/><MobileNav active={view==="operations"} icon={<Activity/>} label="التشغيل" onClick={()=>setView("operations")}/><MobileNav active={view==="finance"} icon={<Wallet/>} label="الحسابات" onClick={()=>setView("finance")}/><MobileNav active={false} icon={<Menu/>} label="المزيد" onClick={()=>setMobileNav(true)}/></div></nav>

    {selected&&<OrderDrawer booking={selected} onClose={()=>setSelected(null)} onMutate={mutateOrder}/>} 
    {commandOpen&&<CommandPalette onClose={()=>setCommandOpen(false)} onNavigate={(v)=>{setView(v);setCommandOpen(false)}} bookings={activeBookings} onOpen={(b)=>{setSelected(b);setCommandOpen(false)}}/>}
    {createCaptainOpen&&<Modal title="إنشاء حساب كابتن" subtitle="الحساب يتفعل مباشرة بعد الحفظ" onClose={()=>setCreateCaptainOpen(false)}><CaptainForm form={captainForm} setForm={setCaptainForm} submit={createCaptain}/></Modal>}
    {editingCaptain&&<Modal title="تعديل حساب الكابتن" subtitle={editingCaptain.name} onClose={()=>{setEditingCaptain(null);setCaptainPassword("")}}><EditCaptainForm captain={editingCaptain} setCaptain={setEditingCaptain} password={captainPassword} setPassword={setCaptainPassword} submit={saveCaptain}/></Modal>}
    {createPromoOpen&&<Modal title="إنشاء رمز خصم" subtitle="اربط الرمز بالشركة ونسبة الخصم" onClose={()=>setCreatePromoOpen(false)}><PromoForm form={promoForm} setForm={setPromoForm} submit={createPromo}/></Modal>}
    {editingPromo&&<Modal title="تعديل رمز الخصم" subtitle={editingPromo.code} onClose={()=>setEditingPromo(null)}><EditPromoForm promo={editingPromo} setPromo={setEditingPromo} submit={savePromo}/></Modal>}
  </main>
}

function LoginScreen({login,setLogin,loading,message,submit}:{login:{username:string;password:string};setLogin:(v:{username:string;password:string})=>void;loading:boolean;message:string;submit:(e:FormEvent)=>void}){return <main dir="rtl" className="min-h-screen bg-[#081f2b] text-white"><div className="grid min-h-screen lg:grid-cols-[1.15fr_.85fr]"><section className="relative hidden overflow-hidden border-l border-white/10 p-12 lg:flex lg:flex-col lg:justify-between"><div className="absolute inset-0 bg-[radial-gradient(circle_at_20%_20%,rgba(214,173,104,.12),transparent_30%),radial-gradient(circle_at_70%_70%,rgba(58,121,151,.18),transparent_35%)]"/><div className="relative flex items-center gap-3"><div className="grid size-14 place-items-center rounded-2xl bg-[#d6ad68] text-[#12384d]"><Plane className="size-7 -rotate-45"/></div><div><div className="text-xs tracking-[.22em] text-white/40">LOUNGE BAGHDAD</div><div className="mt-1 text-xl font-semibold">Enterprise Control Center</div></div></div><div className="relative max-w-xl"><div className="mb-5 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-2 text-xs text-white/60"><Sparkles className="size-4 text-[#d6ad68]"/>منصة تشغيل مركزية</div><h1 className="text-5xl font-semibold leading-[1.2]">كل عمليات الشركة<br/><span className="text-[#d6ad68]">من شاشة واحدة.</span></h1><p className="mt-5 max-w-lg text-base leading-8 text-white/50">طلبات، كباتن، شركات، صالات، خصومات، حسابات، تقارير ومراقبة تشغيل مباشرة.</p></div><div className="relative grid grid-cols-3 gap-3">{[["24/7","مراقبة التشغيل"],["LIVE","حالة الطلبات"],["360°","إدارة مركزية"]].map(([v,l])=><div key={l} className="rounded-2xl border border-white/10 bg-white/[.04] p-4"><div className="text-xl font-semibold text-[#d6ad68]">{v}</div><div className="mt-1 text-xs text-white/35">{l}</div></div>)}</div></section><section className="flex items-center justify-center px-5 py-10"><div className="w-full max-w-md"><div className="mb-8 lg:hidden"><div className="grid size-14 place-items-center rounded-2xl bg-[#d6ad68] text-[#12384d]"><Plane className="size-7 -rotate-45"/></div><h1 className="mt-5 text-2xl font-semibold">مركز إدارة لاونج بغداد</h1></div><div className="mb-7"><div className="text-xs tracking-[.16em] text-[#d6ad68]">SECURE ADMIN ACCESS</div><h2 className="mt-3 text-3xl font-semibold">تسجيل دخول الإدارة</h2><p className="mt-2 text-sm text-white/45">أدخل حساب المدير للوصول إلى مركز التحكم الكامل.</p></div><form onSubmit={submit} className="rounded-[28px] border border-white/10 bg-white/[.055] p-6 shadow-2xl backdrop-blur"><label className="text-xs text-white/55">اسم المستخدم</label><div className="relative mt-2"><UserRound className="absolute right-4 top-1/2 size-4 -translate-y-1/2 text-white/30"/><input dir="ltr" value={login.username} onChange={e=>setLogin({...login,username:e.target.value})} className="h-14 w-full rounded-2xl border border-white/10 bg-black/10 px-11 text-left outline-none focus:border-[#d6ad68]/60" placeholder="admin"/></div><label className="mt-5 block text-xs text-white/55">كلمة المرور</label><div className="relative mt-2"><LockKeyhole className="absolute right-4 top-1/2 size-4 -translate-y-1/2 text-white/30"/><input dir="ltr" type="password" value={login.password} onChange={e=>setLogin({...login,password:e.target.value})} className="h-14 w-full rounded-2xl border border-white/10 bg-black/10 px-11 text-left outline-none focus:border-[#d6ad68]/60" placeholder="••••••"/></div>{message&&<p className="mt-4 rounded-xl bg-red-500/10 px-3 py-2 text-center text-xs text-red-300">{message}</p>}<button disabled={loading} className="mt-6 flex h-14 w-full items-center justify-center gap-2 rounded-2xl bg-[#d6ad68] font-semibold text-[#12384d] shadow-lg shadow-black/20">{loading?<Loader2 className="size-5 animate-spin"/>:<ShieldCheck className="size-5"/>}{loading?"جاري التحقق":"دخول مركز الإدارة"}</button></form></div></section></div></main>}

function Dashboard({overview,newCount,delayed,todayOrders,operations,bookings,captains,promos,loungeReport,companyReport,onNavigate,onOpen}:{overview:Overview|null;newCount:number;delayed:Booking[];todayOrders:Booking[];operations:Operations|null;bookings:Booking[];captains:Captain[];promos:Promo[];loungeReport:{name:string;orders:number;passengers:number}[];companyReport:{name:string;orders:number;passengers:number;captains:Set<string>}[];onNavigate:(v:View)=>void;onOpen:(b:Booking)=>void}){
  const completedRate=todayOrders.length?Math.round(todayOrders.filter(b=>b.status==="completed").length/todayOrders.length*100):0;
  return <div className="space-y-6"><section className="overflow-hidden rounded-[26px] bg-[#10394e] p-5 text-white shadow-[0_20px_45px_rgba(16,57,78,.15)] lg:p-7"><div className="grid gap-6 xl:grid-cols-[1fr_auto]"><div className="text-right"><div className="flex flex-wrap items-center justify-end gap-2"><span className="rounded-full bg-emerald-400/15 px-3 py-1 text-[10px] text-emerald-200"><span className="ml-1 inline-block size-1.5 rounded-full bg-emerald-400"/>النظام يعمل</span><span className="text-xs text-white/40">آخر تحديث الآن</span></div><h2 className="mt-4 text-2xl font-semibold lg:text-3xl">مساء الخير، مركز العمليات جاهز</h2><p className="mt-2 text-sm leading-7 text-white/55">عندك {newCount} طلب جديد و {delayed.length} طلب متأخر يحتاج متابعة.</p></div><div className="grid min-w-[320px] grid-cols-3 gap-2"><HeroMini label="إنجاز اليوم" value={`${completedRate}%`}/><HeroMini label="طلبات نشطة" value={bookings.filter(b=>!["completed","cancelled"].includes(b.status)).length}/><HeroMini label="كباتن فعالين" value={captains.filter(c=>c.active).length}/></div></div></section>
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard title="طلبات اليوم" value={overview?.stats.bookings_today||0} sub={`${newCount} جديد`} icon={<TicketCheck/>} trend="تشغيل مباشر"/><MetricCard title="المسافرون اليوم" value={overview?.stats.passengers_today||0} sub="إجمالي الحركة" icon={<UsersRound/>} trend="كل المصادر"/><MetricCard title="حجوزات الزبائن" value={money(overview?.stats.revenue_today||0)} sub="قيمة اليوم" icon={<CircleDollarSign/>} trend="قبل التسويات" small/><MetricCard title="طلبات متأخرة" value={delayed.length} sub="أكثر من 15 دقيقة" icon={<AlertTriangle/>} trend={delayed.length?"تحتاج متابعة":"الوضع ممتاز"} danger={delayed.length>0}/></section>
    <div className="grid gap-5 xl:grid-cols-[1.5fr_.85fr]"><Panel title="آخر حركة تشغيل" subtitle="الطلبات الأحدث من كل القنوات" action={<button onClick={()=>onNavigate("orders")} className="text-xs font-medium text-[#2a7188]">عرض الكل</button>}><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-right"><thead><tr className="border-b text-[10px] text-slate-400"><Th>الطلب</Th><Th>المصدر</Th><Th>الاسم / الشركة</Th><Th>المسافرون</Th><Th>الحالة</Th><Th>العمر</Th><Th/></tr></thead><tbody>{(overview?.recent||[]).slice(0,7).map(b=><tr key={`${b.source}-${b.id}`} className="border-b border-slate-100 last:border-0"><Td><div className="font-[var(--font-latin)] text-xs font-semibold">{b.reference}</div></Td><Td><SourceBadge source={b.source}/></Td><Td><div className="font-semibold">{b.customer_name}</div><div className="mt-1 text-[10px] text-slate-400">{b.company||b.lounge||b.flight_number||"—"}</div></Td><Td>{b.passengers}</Td><Td><StatusBadge status={b.status}/></Td><Td><span className={ageMinutes(b.created_at)>=15&&b.status==="new"?"font-semibold text-red-600":"text-slate-500"}>{ageLabel(b.created_at)}</span></Td><Td><button onClick={()=>onOpen(b)} className="grid size-8 place-items-center rounded-lg bg-slate-100 text-slate-500 hover:bg-[#eaf2f5] hover:text-[#2a7188]"><Eye className="size-4"/></button></Td></tr>)}</tbody></table></div></Panel>
      <div className="space-y-5"><Panel title="حالة التشغيل" subtitle="قراءة مباشرة للنظام"><div className="space-y-3"><HealthRow label="طلبات جديدة" value={operations?.monitor.new_orders||0} state={(operations?.monitor.new_orders||0)>0?"warn":"good"}/><HealthRow label="طلبات متأخرة" value={operations?.monitor.delayed_orders||0} state={(operations?.monitor.delayed_orders||0)>0?"bad":"good"}/><HealthRow label="أكثر صالة نشاطاً" value={operations?.monitor.busiest_lounge||"—"} state="neutral"/><HealthRow label="أكثر شركة نشطة" value={operations?.monitor.active_company||"—"} state="neutral"/></div></Panel><Panel title="اختصارات سريعة" subtitle="الأكثر استخداماً"><div className="grid grid-cols-2 gap-2"><QuickAction icon={<UserPlus/>} label="إضافة كابتن" onClick={()=>onNavigate("captains")}/><QuickAction icon={<BadgePercent/>} label="رمز خصم" onClick={()=>onNavigate("promos")}/><QuickAction icon={<Wallet/>} label="تسجيل دفعة" onClick={()=>onNavigate("finance")}/><QuickAction icon={<Headphones/>} label="وضع الاستقبال" href="/reception"/></div></Panel></div></div>
    <div className="grid gap-5 xl:grid-cols-3"><RankPanel title="أكثر الصالات حركة" rows={loungeReport.slice(0,5).map(x=>({name:x.name,value:`${x.passengers} مسافر`,sub:`${x.orders} طلب`}))}/><RankPanel title="أكثر الشركات نشاطاً" rows={companyReport.slice(0,5).map(x=>({name:x.name,value:`${x.orders} طلب`,sub:`${x.passengers} مسافر`}))}/><RankPanel title="الخصومات" rows={promos.slice(0,5).map(x=>({name:x.company_name,value:`${x.discount_percent}%`,sub:`${x.uses_count} استخدام`}))}/></div>
  </div>
}

function Orders({bookings,total,filters,setFilters,companies,lounges,showFilters,setShowFilters,duplicatePhones,onOpen,onMutate,onExport}:{bookings:Booking[];total:number;filters:Filters;setFilters:(f:Filters)=>void;companies:string[];lounges:string[];showFilters:boolean;setShowFilters:(v:boolean)=>void;duplicatePhones:Map<string,number>;onOpen:(b:Booking)=>void;onMutate:(id:number,p:Record<string,unknown>)=>void;onExport:()=>void}){return <div className="space-y-5"><PageIntro eyebrow="OPERATIONS" title="إدارة الطلبات" description="متابعة مركزية لكل طلبات الزبائن والكباتن، مع الحالات والأولوية والأرشيف." actions={<><button onClick={onExport} className="btn-secondary"><Download className="size-4"/>تصدير CSV</button></>}/><Panel title="كل الطلبات" subtitle={`${bookings.length} نتيجة من أصل ${total}`} action={<div className="flex gap-2"><button onClick={()=>setShowFilters(!showFilters)} className={`icon-btn ${showFilters?"bg-[#eaf2f5] text-[#2a7188]":""}`}><Filter className="size-4"/></button></div>}><div className="mb-4 flex gap-2"><div className="relative flex-1"><Search className="absolute right-3 top-1/2 size-4 -translate-y-1/2 text-slate-400"/><input value={filters.search} onChange={e=>setFilters({...filters,search:e.target.value})} className="h-11 w-full rounded-xl border border-slate-200 bg-[#fafbfc] pr-10 pl-3 text-sm outline-none focus:border-[#2a7188]" placeholder="ابحث برقم الطلب، الاسم، الهاتف، الشركة..."/></div></div>{showFilters&&<div className="mb-4 grid gap-2 rounded-2xl border border-slate-200 bg-[#fafbfc] p-3 md:grid-cols-3 xl:grid-cols-6"><Select value={filters.status} onChange={v=>setFilters({...filters,status:v})} options={[["all","كل الحالات"],...Object.entries(statusMap).map(([k,v])=>[k,v.label])]}/><Select value={filters.source} onChange={v=>setFilters({...filters,source:v})} options={[["all","كل المصادر"],["captain","الكباتن"],["customer","الزبائن"]]}/><Select value={filters.company} onChange={v=>setFilters({...filters,company:v})} options={[["all","كل الشركات"],...companies.map(x=>[x,x])]}/><Select value={filters.lounge} onChange={v=>setFilters({...filters,lounge:v})} options={[["all","كل الصالات"],...lounges.map(x=>[x,x])]}/><Select value={filters.priority} onChange={v=>setFilters({...filters,priority:v})} options={[["all","كل الأولويات"],["normal","عادي"],["important","مهم"],["urgent","عاجل"]]}/><Select value={filters.archive} onChange={v=>setFilters({...filters,archive:v})} options={[["active","الحالية"],["archived","الأرشيف"],["all","الكل"]]}/><button onClick={()=>setFilters(initialFilters)} className="h-10 rounded-xl bg-white text-xs text-slate-500 md:col-span-3 xl:col-span-6">مسح الفلاتر</button></div>}
      <div className="hidden overflow-x-auto lg:block"><table className="w-full min-w-[1050px] text-right"><thead><tr className="border-y bg-[#fafbfc] text-[10px] text-slate-400"><Th>الطلب</Th><Th>المصدر</Th><Th>الاسم</Th><Th>الشركة / الصالة</Th><Th>الهاتف</Th><Th>المسافرون</Th><Th>الأولوية</Th><Th>الحالة</Th><Th>الوقت</Th><Th/></tr></thead><tbody>{bookings.map(b=><tr key={`${b.source}-${b.id}`} className="group border-b border-slate-100 hover:bg-[#fbfcfd]"><Td><div className="font-[var(--font-latin)] text-xs font-bold text-[#183b50]">{b.reference}</div>{duplicatePhones.get(b.phone)!>1&&<span className="mt-1 inline-flex items-center gap-1 text-[9px] text-orange-600"><AlertTriangle className="size-3"/>رقم مكرر</span>}</Td><Td><SourceBadge source={b.source}/></Td><Td><div className="font-semibold">{b.customer_name}</div><div className="mt-1 text-[10px] text-slate-400">{b.flight_number||"—"}</div></Td><Td><div>{b.company||b.lounge||"—"}</div>{b.company&&b.lounge&&<div className="mt-1 text-[10px] text-slate-400">{b.lounge}</div>}</Td><Td><a dir="ltr" href={`tel:${b.phone}`} className="text-xs text-[#2a7188]">{b.phone}</a></Td><Td>{b.passengers}</Td><Td><PriorityBadge p={b.priority}/></Td><Td><StatusBadge status={b.status}/></Td><Td><div className="text-xs">{ageLabel(b.created_at)}</div><div className="mt-1 text-[9px] text-slate-400">{dateTime(b.created_at)}</div></Td><Td><button onClick={()=>onOpen(b)} className="icon-btn"><Eye className="size-4"/></button></Td></tr>)}</tbody></table></div>
      <div className="space-y-3 lg:hidden">{bookings.map(b=><article key={`${b.source}-${b.id}`} className="rounded-2xl border border-slate-200 p-4"><div className="flex items-start justify-between gap-3"><button onClick={()=>onOpen(b)} className="icon-btn"><Eye className="size-4"/></button><div className="text-right"><div className="flex items-center justify-end gap-2"><SourceBadge source={b.source}/><span className="font-[var(--font-latin)] text-[10px] text-slate-400">{b.reference}</span></div><h3 className="mt-2 font-semibold">{b.customer_name}</h3><p className="mt-1 text-xs text-slate-400">{b.company||b.lounge||b.flight_number||"—"}</p></div></div><div className="mt-3 grid grid-cols-3 gap-2"><Mini label="المسافرون" value={b.passengers}/><Mini label="الأولوية" value={priorityMap[b.priority]?.label||"عادي"}/><Mini label="العمر" value={ageLabel(b.created_at)}/></div><div className="mt-3 flex gap-2 overflow-x-auto">{Object.entries(statusMap).map(([k,v])=><button key={k} onClick={()=>onMutate(b.id,{status:k})} className={`shrink-0 rounded-lg px-3 py-2 text-[10px] ${b.status===k?"bg-[#123f58] text-white":"bg-slate-100 text-slate-500"}`}>{v.label}</button>)}</div></article>)}</div>{!bookings.length&&<Empty text="ماكو طلبات تطابق البحث الحالي"/>}</Panel></div>}

function OperationsView({data,delayed,newCount,messages,newMessage,setNewMessage,watchForm,setWatchForm,action}:{data:Operations|null;delayed:Booking[];newCount:number;messages:SystemMessage[];newMessage:string;setNewMessage:(v:string)=>void;watchForm:{kind:string;value:string;note:string};setWatchForm:(v:{kind:string;value:string;note:string})=>void;action:(m:"POST"|"PATCH"|"DELETE",b?:Record<string,unknown>,q?:string)=>Promise<boolean>}){return <div className="space-y-5"><PageIntro eyebrow="LIVE OPS" title="مركز العمليات" description="شاشة مراقبة فورية لحركة الطلبات، التنبيهات ورسائل الكباتن."/><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><MetricCard title="طلبات جديدة" value={newCount} sub="بانتظار الاستلام" icon={<BellRing/>}/><MetricCard title="متأخرة" value={delayed.length} sub="أكثر من 15 دقيقة" icon={<AlertTriangle/>} danger={delayed.length>0}/><MetricCard title="أقدم طلب" value={data?.monitor.oldest_new?ageLabel(data.monitor.oldest_new):"—"} sub="من الطلبات الجديدة" icon={<Clock3/>} small/><MetricCard title="الصالة الأكثر ضغطاً" value={data?.monitor.busiest_lounge||"—"} sub="حسب الحركة" icon={<Armchair/>} small/><MetricCard title="الشركة الأنشط" value={data?.monitor.active_company||"—"} sub="آخر 24 ساعة" icon={<Building2/>} small/></div><div className="grid gap-5 xl:grid-cols-2"><Panel title="رسائل النظام للكباتن" subtitle="تظهر مباشرة داخل بوابة الكابتن"><form onSubmit={async e=>{e.preventDefault();if(await action("POST",{action:"message",text:newMessage}))setNewMessage("")}} className="flex gap-2"><input value={newMessage} onChange={e=>setNewMessage(e.target.value)} className="field" placeholder="مثال: صالة بابل متوقفة مؤقتاً"/><button className="btn-primary shrink-0"><Plus className="size-4"/>نشر</button></form><div className="mt-4 space-y-2">{messages.map(m=><div key={m.id} className="flex items-center gap-3 rounded-xl bg-[#f7f9fa] p-3"><button onClick={()=>action("DELETE",undefined,`?action=message&id=${m.id}`)} className="text-red-500"><Trash2 className="size-4"/></button><button onClick={()=>action("PATCH",{action:"message",id:m.id,active:!m.active})} className={m.active?"text-emerald-600":"text-slate-400"}><Power className="size-4"/></button><div className="flex-1 text-right"><div className="text-sm">{m.text}</div><div className="mt-1 text-[9px] text-slate-400">{dateTime(m.created_at)}</div></div></div>)}{!messages.length&&<Empty text="ماكو رسائل نظام حالياً"/>}</div></Panel><Panel title="قائمة المراقبة والحظر" subtitle="رقم مسافر، كابتن أو شركة"><form onSubmit={async e=>{e.preventDefault();if(await action("POST",{action:"watch",...watchForm}))setWatchForm({kind:"phone",value:"",note:""})}} className="grid gap-2 sm:grid-cols-[130px_1fr_1fr_auto]"><Select value={watchForm.kind} onChange={v=>setWatchForm({...watchForm,kind:v})} options={[["phone","رقم مسافر"],["captain","كابتن"],["company","شركة"]]}/><input value={watchForm.value} onChange={e=>setWatchForm({...watchForm,value:e.target.value})} className="field" placeholder="القيمة"/><input value={watchForm.note} onChange={e=>setWatchForm({...watchForm,note:e.target.value})} className="field" placeholder="السبب / الملاحظة"/><button className="btn-primary"><Plus className="size-4"/></button></form><div className="mt-4 space-y-2">{(data?.watchlist||[]).slice(0,10).map(w=><div key={w.id} className="flex items-center gap-3 rounded-xl border border-slate-100 p-3"><button onClick={()=>action("DELETE",undefined,`?action=watch&id=${w.id}`)} className="text-red-500"><Trash2 className="size-4"/></button><button onClick={()=>action("PATCH",{action:"watch",id:w.id,active:!w.active})} className={w.active?"text-emerald-600":"text-slate-400"}><Power className="size-4"/></button><div className="flex-1 text-right"><div className="flex justify-end gap-2"><span className="text-xs font-semibold">{w.value}</span><span className="rounded bg-slate-100 px-2 py-1 text-[9px] text-slate-500">{w.kind==="phone"?"رقم":w.kind==="captain"?"كابتن":"شركة"}</span></div><div className="mt-1 text-[10px] text-slate-400">{w.note||"بدون ملاحظة"}</div></div></div>)}{!data?.watchlist?.length&&<Empty text="قائمة المراقبة فارغة"/>}</div></Panel></div></div>}

function CaptainsView({captains,report,onCreate,onEdit,onToggle,onDelete}:{captains:Captain[];report:{name:string;company:string;orders:number;passengers:number}[];onCreate:()=>void;onEdit:(c:Captain)=>void;onToggle:(c:Captain)=>void;onDelete:(c:Captain)=>void}){return <div className="space-y-5"><PageIntro eyebrow="PARTNERS" title="إدارة الكباتن" description="إنشاء وإدارة حسابات الكباتن ومتابعة نشاط كل كابتن." actions={<button onClick={onCreate} className="btn-primary"><UserPlus className="size-4"/>إضافة كابتن</button>}/><div className="grid gap-3 sm:grid-cols-3"><MetricCard title="إجمالي الكباتن" value={captains.length} sub="كل الحسابات" icon={<UsersRound/>}/><MetricCard title="الحسابات الفعالة" value={captains.filter(c=>c.active).length} sub="يمكنها تسجيل الدخول" icon={<ShieldCheck/>}/><MetricCard title="كباتن عندهم نشاط" value={report.length} sub="ضمن الطلبات المحفوظة" icon={<Activity/>}/></div><Panel title="دليل الكباتن" subtitle="إدارة الحسابات من نفس لوحة الأدمن"><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-right"><thead><tr className="border-y bg-[#fafbfc] text-[10px] text-slate-400"><Th>الكابتن</Th><Th>الشركة</Th><Th>اسم المستخدم</Th><Th>الهاتف</Th><Th>النشاط</Th><Th>الحالة</Th><Th>الإجراءات</Th></tr></thead><tbody>{captains.map(c=>{const r=report.find(x=>x.name===c.name&&x.company===(c.company||"—"));return <tr key={c.id} className="border-b border-slate-100"><Td><div className="flex items-center justify-end gap-3"><div><div className="font-semibold">{c.name}</div><div className="mt-1 text-[10px] text-slate-400">ID {c.id}</div></div><div className="grid size-9 place-items-center rounded-xl bg-[#eaf2f5] font-semibold text-[#2a7188]">{c.name.charAt(0)}</div></div></Td><Td>{c.company||"—"}</Td><Td><span dir="ltr" className="font-[var(--font-latin)] text-xs">@{c.username}</span></Td><Td><a dir="ltr" href={`tel:${c.phone}`} className="text-xs text-[#2a7188]">{c.phone||"—"}</a></Td><Td><div className="font-semibold">{r?.orders||0} طلب</div><div className="mt-1 text-[10px] text-slate-400">{r?.passengers||0} مسافر</div></Td><Td><span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[10px] ${c.active?"bg-emerald-50 text-emerald-700":"bg-slate-100 text-slate-500"}`}><span className={`size-1.5 rounded-full ${c.active?"bg-emerald-400":"bg-slate-400"}`}/>{c.active?"فعال":"موقوف"}</span></Td><Td><div className="flex gap-1"><button onClick={()=>onEdit(c)} className="icon-btn"><Edit3 className="size-4"/></button><button onClick={()=>onToggle(c)} className="icon-btn"><Power className="size-4"/></button><button onClick={()=>onDelete(c)} className="icon-btn text-red-500"><Trash2 className="size-4"/></button></div></Td></tr>})}</tbody></table></div></Panel></div>}

function CompaniesView({companies,overview,captains,promos,bookings,onNavigate}:{companies:CompanyAccount[];overview:CompanyOverview[];captains:Captain[];promos:Promo[];bookings:Booking[];onNavigate:(v:View)=>void}){const names=Array.from(new Set([...companies.map(c=>c.name),...overview.map(c=>c.name)])).sort();return <div className="space-y-5"><PageIntro eyebrow="B2B" title="الشركات والشركاء" description="ملف موحد لكل شركة: كباتن، طلبات، مسافرين، خصومات وحساب مالي."/><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{names.map(name=>{const acc=companies.find(c=>c.name===name);const ovs=overview.find(c=>c.name===name);const cc=captains.filter(c=>c.company===name);const pp=promos.filter(p=>p.company_name===name);const bb=bookings.filter(b=>b.company===name);const balance=Number(acc?.due_iqd||0)-Number(acc?.paid_iqd||0);return <article key={name} className="rounded-[22px] border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><span className="rounded-full bg-[#eaf2f5] px-2.5 py-1 text-[9px] font-semibold text-[#2a7188]">PARTNER</span><div className="flex items-center gap-3"><div className="text-right"><h3 className="font-bold">{name}</h3><p className="mt-1 text-[10px] text-slate-400">شركة شريكة</p></div><div className="grid size-11 place-items-center rounded-2xl bg-[#10394e] text-white"><Building2 className="size-5"/></div></div></div><div className="mt-5 grid grid-cols-4 gap-2"><Mini label="كباتن" value={cc.length||ovs?.captains||0}/><Mini label="طلبات" value={bb.length||acc?.orders||0}/><Mini label="مسافرين" value={acc?.passengers||bb.reduce((s,b)=>s+b.passengers,0)}/><Mini label="خصومات" value={pp.length||ovs?.promos||0}/></div><div className="mt-4 rounded-xl bg-[#f7f9fa] p-3"><div className="flex justify-between text-xs"><span className={balance>0?"font-bold text-red-600":"font-bold text-emerald-600"}>{money(balance)}</span><span className="text-slate-400">الرصيد المتبقي</span></div></div><div className="mt-4 flex gap-2"><button onClick={()=>onNavigate("finance")} className="btn-secondary flex-1"><Wallet className="size-4"/>الحساب</button><button onClick={()=>onNavigate("captains")} className="btn-secondary flex-1"><UsersRound className="size-4"/>الكباتن</button></div></article>})}</div>{!names.length&&<Empty text="ماكو شركات مضافة حالياً"/>}</div>}

function PromosView({promos,onCreate,onEdit,onToggle,onDelete}:{promos:Promo[];onCreate:()=>void;onEdit:(p:Promo)=>void;onToggle:(p:Promo)=>void;onDelete:(p:Promo)=>void}){return <div className="space-y-5"><PageIntro eyebrow="PARTNER PROMOS" title="إدارة الخصومات" description="رموز خصم الشركات مع النسبة والصلاحية وحدود الاستخدام." actions={<button onClick={onCreate} className="btn-primary"><Plus className="size-4"/>رمز جديد</button>}/><div className="grid gap-3 sm:grid-cols-3"><MetricCard title="إجمالي الرموز" value={promos.length} sub="كل الرموز" icon={<BadgePercent/>}/><MetricCard title="الرموز الفعالة" value={promos.filter(p=>p.active).length} sub="جاهزة للاستخدام" icon={<Zap/>}/><MetricCard title="مرات الاستخدام" value={promos.reduce((s,p)=>s+p.uses_count,0)} sub="إجمالي الاستخدام" icon={<TicketCheck/>}/></div><Panel title="رموز الشركات" subtitle="إدارة كاملة من داخل لوحة الأدمن"><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-right"><thead><tr className="border-y bg-[#fafbfc] text-[10px] text-slate-400"><Th>الشركة</Th><Th>الرمز</Th><Th>الخصم</Th><Th>الاستخدام</Th><Th>الصلاحية</Th><Th>الحالة</Th><Th>الإجراءات</Th></tr></thead><tbody>{promos.map(p=>{const expired=p.expires_at&&new Date(p.expires_at)<new Date();const exhausted=p.max_uses!==null&&p.uses_count>=p.max_uses;return <tr key={p.id} className="border-b border-slate-100"><Td className="font-semibold">{p.company_name}</Td><Td><button onClick={()=>navigator.clipboard?.writeText(p.code)} className="inline-flex items-center gap-2 rounded-lg bg-slate-100 px-3 py-2 font-[var(--font-latin)] text-xs font-bold"><Copy className="size-3"/>{p.code}</button></Td><Td><span className="font-bold text-[#2a7188]">{p.discount_percent}%</span></Td><Td>{p.uses_count}{p.max_uses?` / ${p.max_uses}`:""}</Td><Td>{p.expires_at?dateOnly(p.expires_at):"بدون انتهاء"}</Td><Td><span className={`rounded-full px-2.5 py-1 text-[10px] ${p.active&&!expired&&!exhausted?"bg-emerald-50 text-emerald-700":"bg-slate-100 text-slate-500"}`}>{expired?"منتهي":exhausted?"مكتمل":p.active?"فعال":"موقوف"}</span></Td><Td><div className="flex gap-1"><button onClick={()=>onEdit(p)} className="icon-btn"><Edit3 className="size-4"/></button><button onClick={()=>onToggle(p)} className="icon-btn"><Power className="size-4"/></button><button onClick={()=>onDelete(p)} className="icon-btn text-red-500"><Trash2 className="size-4"/></button></div></Td></tr>})}</tbody></table></div></Panel></div>}

function LoungesView({lounges,report,action}:{lounges:Lounge[];report:{name:string;orders:number;passengers:number}[];action:(m:"POST"|"PATCH"|"DELETE",b?:Record<string,unknown>,q?:string)=>Promise<boolean>}){return <div className="space-y-5"><PageIntro eyebrow="SERVICE CONTROL" title="إدارة الصالات" description="تحكم مباشر بحالة الصالة، الاسم، السعر، الترتيب والملاحظات."/><div className="grid gap-4 lg:grid-cols-2 xl:grid-cols-3">{lounges.map(l=>{const r=report.find(x=>x.name===l.name);return <LoungeCard key={l.id} lounge={l} activity={r} save={async x=>{await action("PATCH",{action:"lounge",id:x.id,name:x.name,active:x.active,priceIqd:x.price_iqd,note:x.note,sortOrder:x.sort_order})}}/>})}</div></div>}

function LoungeCard({lounge,activity,save}:{lounge:Lounge;activity?:{orders:number;passengers:number};save:(l:Lounge)=>Promise<void>}){const [l,setL]=useState(lounge);useEffect(()=>setL(lounge),[lounge]);return <article className="rounded-[22px] border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><button onClick={()=>setL({...l,active:!l.active})} className={`rounded-full px-3 py-1 text-[10px] ${l.active?"bg-emerald-50 text-emerald-700":"bg-slate-100 text-slate-500"}`}>{l.active?"مفتوحة":"متوقفة"}</button><div className="flex items-center gap-3"><div className="text-right"><div className="font-bold">{l.name}</div><div className="mt-1 text-[10px] text-slate-400">ID: {l.id}</div></div><div className="grid size-11 place-items-center rounded-2xl bg-[#eaf2f5] text-[#2a7188]"><Armchair className="size-5"/></div></div></div><div className="mt-4 grid grid-cols-2 gap-2"><Mini label="الطلبات" value={activity?.orders||0}/><Mini label="المسافرون" value={activity?.passengers||0}/></div><label className="mt-4 block"><span className="label">اسم الصالة</span><input value={l.name} onChange={e=>setL({...l,name:e.target.value})} className="field mt-1"/></label><label className="mt-3 block"><span className="label">سعر الشخص</span><input type="number" dir="ltr" value={l.price_iqd} onChange={e=>setL({...l,price_iqd:Number(e.target.value)})} className="field mt-1"/></label><label className="mt-3 block"><span className="label">ملاحظة</span><textarea value={l.note} onChange={e=>setL({...l,note:e.target.value})} className="field mt-1 min-h-20 py-3"/></label><button onClick={()=>save(l)} className="btn-primary mt-4 w-full"><Save className="size-4"/>حفظ إعدادات الصالة</button></article>}

function FinanceView({companies,total,paid,paymentForm,setPaymentForm,action}:{companies:CompanyAccount[];total:number;paid:number;paymentForm:{companyName:string;amountIqd:string;note:string};setPaymentForm:(v:{companyName:string;amountIqd:string;note:string})=>void;action:(m:"POST"|"PATCH"|"DELETE",b?:Record<string,unknown>,q?:string)=>Promise<boolean>}){const balance=total-paid;return <div className="space-y-5"><PageIntro eyebrow="FINANCE" title="الحسابات المالية" description="مستحقات الشركات، المدفوعات والأرصدة المتبقية حسب سعر المسافر."/><div className="grid gap-3 sm:grid-cols-3"><MetricCard title="إجمالي المستحق" value={money(total)} sub="كل الشركات" icon={<Wallet/>} small/><MetricCard title="إجمالي المدفوع" value={money(paid)} sub="الدفعات المسجلة" icon={<CreditCard/>} small/><MetricCard title="الرصيد المتبقي" value={money(balance)} sub="قيد التحصيل" icon={<CircleDollarSign/>} small danger={balance>0}/></div><div className="grid gap-5 xl:grid-cols-[1.5fr_.7fr]"><Panel title="حسابات الشركات" subtitle="الرصيد = المستحق - المدفوع"><div className="overflow-x-auto"><table className="w-full min-w-[780px] text-right"><thead><tr className="border-y bg-[#fafbfc] text-[10px] text-slate-400"><Th>الشركة</Th><Th>المسافرون</Th><Th>سعر الشخص</Th><Th>المستحق</Th><Th>المدفوع</Th><Th>المتبقي</Th><Th/></tr></thead><tbody>{companies.map(c=>{const b=Number(c.due_iqd)-Number(c.paid_iqd);return <CompanyFinanceRow key={c.name} company={c} balance={b} save={async(price,notes)=>{await action("PATCH",{action:"company",companyName:c.name,pricePerPassenger:price,notes})}}/>})}</tbody></table></div></Panel><Panel title="تسجيل دفعة" subtitle="إضافة دفعة جديدة لحساب شركة"><form onSubmit={async e=>{e.preventDefault();if(await action("POST",{action:"payment",companyName:paymentForm.companyName,amountIqd:Number(paymentForm.amountIqd),note:paymentForm.note}))setPaymentForm({companyName:"",amountIqd:"",note:""})}} className="space-y-3"><label><span className="label">الشركة</span><Select value={paymentForm.companyName} onChange={v=>setPaymentForm({...paymentForm,companyName:v})} options={[["","اختر الشركة"],...companies.map(c=>[c.name,c.name])]}/></label><label className="block"><span className="label">المبلغ</span><input dir="ltr" type="number" value={paymentForm.amountIqd} onChange={e=>setPaymentForm({...paymentForm,amountIqd:e.target.value})} className="field mt-1" placeholder="0"/></label><label className="block"><span className="label">ملاحظة الدفعة</span><textarea value={paymentForm.note} onChange={e=>setPaymentForm({...paymentForm,note:e.target.value})} className="field mt-1 min-h-24 py-3" placeholder="اختياري"/></label><button className="btn-primary w-full"><CreditCard className="size-4"/>تسجيل الدفعة</button></form></Panel></div></div>}

function CompanyFinanceRow({company,balance,save}:{company:CompanyAccount;balance:number;save:(p:number,n:string)=>Promise<void>}){const [edit,setEdit]=useState(false);const [price,setPrice]=useState(company.price_per_passenger);const [notes,setNotes]=useState(company.notes||"");useEffect(()=>{setPrice(company.price_per_passenger);setNotes(company.notes||"")},[company]);return <tr className="border-b border-slate-100"><Td><div className="font-semibold">{company.name}</div>{edit&&<input value={notes} onChange={e=>setNotes(e.target.value)} className="mt-2 h-8 w-44 rounded-lg border px-2 text-[10px]" placeholder="ملاحظة"/>}</Td><Td>{company.passengers}</Td><Td>{edit?<input type="number" dir="ltr" value={price} onChange={e=>setPrice(Number(e.target.value))} className="h-9 w-28 rounded-lg border px-2 text-left text-xs"/>:money(company.price_per_passenger)}</Td><Td>{money(company.due_iqd)}</Td><Td className="text-emerald-700">{money(company.paid_iqd)}</Td><Td><span className={balance>0?"font-bold text-red-600":"font-bold text-emerald-700"}>{money(balance)}</span></Td><Td>{edit?<button onClick={async()=>{await save(price,notes);setEdit(false)}} className="icon-btn text-emerald-700"><Save className="size-4"/></button>:<button onClick={()=>setEdit(true)} className="icon-btn"><Edit3 className="size-4"/></button>}</Td></tr>}

function ReportsView({bookings,captainReport,companyReport,loungeReport}:{bookings:Booking[];captainReport:{name:string;company:string;orders:number;passengers:number}[];companyReport:{name:string;orders:number;passengers:number;captains:Set<string>}[];loungeReport:{name:string;orders:number;passengers:number}[]}){const byHour=useMemo(()=>{const a=Array.from({length:24},(_,h)=>({h,count:0}));bookings.forEach(b=>{const h=Number(new Intl.DateTimeFormat("en",{timeZone:"Asia/Baghdad",hour:"2-digit",hourCycle:"h23"}).format(new Date(b.created_at)));if(Number.isFinite(h))a[h].count++});return a},[bookings]);const max=Math.max(1,...byHour.map(x=>x.count));return <div className="space-y-5"><PageIntro eyebrow="ANALYTICS" title="التقارير والتحليلات" description="قراءة تشغيلية لنشاط الكباتن والشركات والصالات وأوقات الضغط."/><Panel title="توزيع الطلبات حسب الساعة" subtitle="يعطيك فكرة عن ساعات الضغط خلال اليوم"><div dir="ltr" className="flex h-52 items-end gap-1 overflow-x-auto pt-8">{byHour.map(x=><div key={x.h} className="flex min-w-7 flex-1 flex-col items-center gap-2"><div className="w-full rounded-t bg-[#2a7188]/80" style={{height:`${Math.max(4,x.count/max*150)}px`}} title={`${x.count} طلب`}/><span className="text-[8px] text-slate-400">{String(x.h).padStart(2,"0")}</span></div>)}</div></Panel><div className="grid gap-5 xl:grid-cols-3"><RankPanel title="أفضل الكباتن" rows={captainReport.slice(0,10).map(x=>({name:x.name,value:`${x.orders} طلب`,sub:`${x.passengers} مسافر · ${x.company}`}))}/><RankPanel title="أفضل الشركات" rows={companyReport.slice(0,10).map(x=>({name:x.name,value:`${x.orders} طلب`,sub:`${x.passengers} مسافر · ${x.captains.size} كابتن`}))}/><RankPanel title="نشاط الصالات" rows={loungeReport.slice(0,10).map(x=>({name:x.name,value:`${x.passengers} مسافر`,sub:`${x.orders} طلب`}))}/></div></div>}

function ActivityView({rows}:{rows:ActivityRow[]}){return <div className="space-y-5"><PageIntro eyebrow="AUDIT LOG" title="سجل النشاط" description="سجل مركزي للتغييرات التي تحصل على الطلبات داخل النظام."/><Panel title="آخر التغييرات" subtitle={`${rows.length} حركة محفوظة`}><div className="space-y-0">{rows.map((r,i)=><div key={r.id} className="relative flex gap-4 py-4 pr-1 after:absolute after:right-[17px] after:top-11 after:h-[calc(100%-20px)] after:w-px after:bg-slate-100 last:after:hidden"><div className="z-10 grid size-9 shrink-0 place-items-center rounded-full border border-slate-200 bg-white text-[#2a7188]"><History className="size-4"/></div><div className="flex-1 text-right"><div className="flex flex-wrap items-center justify-between gap-2"><span className="text-[10px] text-slate-400">{dateTime(r.created_at)}</span><div className="font-semibold">{r.reference}</div></div><div className="mt-1 text-xs text-slate-500">{activityLabel(r.action)}{r.new_value?` — ${r.new_value}`:""}</div><div className="mt-1 text-[9px] text-slate-400">بواسطة {r.actor||"الإدارة"}</div></div></div>)}{!rows.length&&<Empty text="ماكو نشاط مسجل لحد الآن"/>}</div></Panel></div>}

function SettingsView({sound,setSound,newCount}:{sound:boolean;setSound:(v:boolean)=>void;newCount:number}){return <div className="space-y-5"><PageIntro eyebrow="SYSTEM" title="إعدادات النظام" description="إعدادات تشغيلية عامة وروابط الأنظمة المساعدة."/><div className="grid gap-5 xl:grid-cols-2"><Panel title="التنبيهات" subtitle="تحكم بتنبيه الطلبات الجديدة"><SettingRow icon={<BellRing/>} title="صوت الطلب الجديد" description="تشغيل صوت خفيف عند اكتشاف طلب جديد" control={<button onClick={()=>setSound(!sound)} className={`relative h-7 w-12 rounded-full transition ${sound?"bg-emerald-500":"bg-slate-300"}`}><span className={`absolute top-1 size-5 rounded-full bg-white shadow transition ${sound?"right-6":"right-1"}`}/></button>}/><SettingRow icon={<Clock3/>} title="حد التأخير" description="حالياً يتم اعتبار الطلب متأخراً بعد 15 دقيقة" control={<span className="rounded-lg bg-slate-100 px-3 py-2 text-xs">15 دقيقة</span>}/><SettingRow icon={<Bell/>} title="طلبات جديدة" description="عدد الطلبات الجديدة حالياً" control={<span className="rounded-lg bg-amber-50 px-3 py-2 text-xs font-bold text-amber-700">{newCount}</span>}/></Panel><Panel title="بوابات النظام" subtitle="الوصول السريع للواجهات التشغيلية"><LinkRow href="/reception" title="شاشة الاستقبال" sub="واجهة تشغيل مبسطة للموظفين" icon={<Headphones/>}/><LinkRow href="/captain" title="بوابة الكباتن" sub="واجهة إرسال طلبات الصالات" icon={<UsersRound/>}/><LinkRow href="/prmos" title="لوحة الخصومات القديمة" sub="تبقى متاحة بشكل مستقل" icon={<BadgePercent/>}/><LinkRow href="/admin/operations" title="مركز التشغيل المستقل" sub="نسخة مستقلة من إعدادات التشغيل" icon={<SlidersHorizontal/>}/></Panel></div></div>}

function OrderDrawer({booking,onClose,onMutate}:{booking:Booking;onClose:()=>void;onMutate:(id:number,p:Record<string,unknown>)=>void}){const [note,setNote]=useState(booking.internal_note||"");useEffect(()=>setNote(booking.internal_note||""),[booking]);return <div className="fixed inset-0 z-[70] bg-black/35" onClick={onClose}><aside onClick={e=>e.stopPropagation()} className="absolute inset-y-0 left-0 w-full max-w-[520px] overflow-y-auto bg-white shadow-2xl"><div className="sticky top-0 z-10 border-b bg-white/95 px-5 py-4 backdrop-blur"><div className="flex items-center justify-between"><button onClick={onClose} className="icon-btn"><X className="size-4"/></button><div className="text-right"><div className="flex items-center justify-end gap-2"><SourceBadge source={booking.source}/><span className="font-[var(--font-latin)] text-[10px] text-slate-400">{booking.reference}</span></div><h2 className="mt-2 text-xl font-bold">{booking.customer_name}</h2></div></div></div><div className="space-y-5 p-5"><div className="grid grid-cols-2 gap-2"><Detail label="رقم الهاتف" value={booking.phone} icon={<Phone/>}/><Detail label="المسافرون" value={String(booking.passengers)} icon={<UsersRound/>}/><Detail label="الحقائب" value={String(booking.bags)} icon={<Luggage/>}/><Detail label="وقت الطلب" value={dateTime(booking.created_at)} icon={<CalendarDays/>}/>{booking.source==="captain"?<><Detail label="الشركة" value={booking.company||"—"} icon={<Building2/>}/><Detail label="الصالة" value={booking.lounge||"—"} icon={<Armchair/>}/><Detail label="العربات" value={String(booking.carts||0)} icon={<BriefcaseBusiness/>}/></>:<><Detail label="رقم الرحلة" value={booking.flight_number||"—"} icon={<Plane/>}/><Detail label="الإجمالي" value={money(booking.total_iqd)} icon={<CircleDollarSign/>}/><Detail label="رمز الخصم" value={booking.promo_code||"بدون"} icon={<BadgePercent/>}/></>}</div><section><SectionHead title="حالة الطلب"/><div className="grid grid-cols-2 gap-2 sm:grid-cols-5">{Object.entries(statusMap).map(([k,v])=><button key={k} onClick={()=>onMutate(booking.id,{status:k})} className={`rounded-xl px-2 py-3 text-[10px] font-semibold ${booking.status===k?"bg-[#10394e] text-white":v.badge}`}>{v.label}</button>)}</div></section><section><SectionHead title="الأولوية"/><div className="grid grid-cols-3 gap-2">{Object.entries(priorityMap).map(([k,v])=><button key={k} onClick={()=>onMutate(booking.id,{priority:k})} className={`rounded-xl px-3 py-3 text-xs ${booking.priority===k?"bg-[#10394e] text-white":v.badge}`}>{v.label}</button>)}</div></section><section><SectionHead title="ملاحظة داخلية"/><textarea value={note} onChange={e=>setNote(e.target.value)} className="field min-h-28 py-3" placeholder="ملاحظة لا تظهر للزبون أو الكابتن"/><button onClick={()=>onMutate(booking.id,{internalNote:note})} className="btn-primary mt-2"><Save className="size-4"/>حفظ الملاحظة</button></section><div className="grid grid-cols-2 gap-2"><a href={`tel:${booking.phone}`} className="btn-secondary justify-center"><Phone className="size-4"/>اتصال</a><button onClick={()=>onMutate(booking.id,{archived:!booking.archived_at})} className="btn-secondary justify-center">{booking.archived_at?<RotateCcw className="size-4"/>:<Archive className="size-4"/>}{booking.archived_at?"إرجاع من الأرشيف":"أرشفة"}</button></div></div></aside></div>}

function CommandPalette({onClose,onNavigate,bookings,onOpen}:{onClose:()=>void;onNavigate:(v:View)=>void;bookings:Booking[];onOpen:(b:Booking)=>void}){const [q,setQ]=useState("");const results=bookings.filter(b=>[b.reference,b.customer_name,b.phone,b.company||""].join(" ").toLowerCase().includes(q.toLowerCase())).slice(0,6);return <div className="fixed inset-0 z-[80] flex items-start justify-center bg-black/40 px-4 pt-[10vh]" onClick={onClose}><div onClick={e=>e.stopPropagation()} className="w-full max-w-2xl overflow-hidden rounded-[22px] border border-slate-200 bg-white shadow-2xl"><div className="flex items-center gap-3 border-b px-4"><Search className="size-5 text-slate-400"/><input autoFocus value={q} onChange={e=>setQ(e.target.value)} className="h-16 flex-1 outline-none" placeholder="ابحث عن طلب أو انتقل إلى قسم..."/><button onClick={onClose}><X className="size-4 text-slate-400"/></button></div><div className="max-h-[60vh] overflow-y-auto p-2">{!q&&<><div className="px-3 py-2 text-[10px] font-semibold text-slate-400">انتقال سريع</div><div className="grid grid-cols-2 gap-1">{navGroups.flatMap(g=>g.items).map(x=><button key={x.id} onClick={()=>onNavigate(x.id)} className="flex items-center gap-3 rounded-xl px-3 py-3 text-right hover:bg-slate-50"><x.icon className="size-4 text-[#2a7188]"/><span className="text-sm">{x.label}</span></button>)}</div></>}{q&&<><div className="px-3 py-2 text-[10px] font-semibold text-slate-400">نتائج الطلبات</div>{results.map(b=><button key={`${b.source}-${b.id}`} onClick={()=>onOpen(b)} className="flex w-full items-center justify-between rounded-xl px-3 py-3 hover:bg-slate-50"><ChevronLeft className="size-4 text-slate-300"/><div className="text-right"><div className="text-sm font-semibold">{b.customer_name}</div><div className="mt-1 text-[10px] text-slate-400">{b.reference} · {b.phone}</div></div></button>)}{!results.length&&<Empty text="ماكو نتيجة"/>}</>}</div></div></div>}

function CaptainForm({form,setForm,submit}:{form:{name:string;company:string;phone:string;username:string;password:string};setForm:(v:{name:string;company:string;phone:string;username:string;password:string})=>void;submit:(e:FormEvent)=>void}){return <form onSubmit={submit} className="grid gap-3 sm:grid-cols-2"><Field label="اسم الكابتن" value={form.name} onChange={v=>setForm({...form,name:v})}/><Field label="الشركة" value={form.company} onChange={v=>setForm({...form,company:v})}/><Field label="الهاتف" value={form.phone} onChange={v=>setForm({...form,phone:v})} dir="ltr"/><Field label="اسم المستخدم" value={form.username} onChange={v=>setForm({...form,username:v})} dir="ltr"/><Field label="كلمة المرور" value={form.password} onChange={v=>setForm({...form,password:v})} dir="ltr" type="password" className="sm:col-span-2"/><button className="btn-primary mt-2 sm:col-span-2"><Check className="size-4"/>إنشاء الحساب</button></form>}
function EditCaptainForm({captain,setCaptain,password,setPassword,submit}:{captain:Captain;setCaptain:(v:Captain)=>void;password:string;setPassword:(v:string)=>void;submit:(e:FormEvent)=>void}){return <form onSubmit={submit} className="grid gap-3 sm:grid-cols-2"><Field label="اسم الكابتن" value={captain.name} onChange={v=>setCaptain({...captain,name:v})}/><Field label="الشركة" value={captain.company} onChange={v=>setCaptain({...captain,company:v})}/><Field label="الهاتف" value={captain.phone} onChange={v=>setCaptain({...captain,phone:v})} dir="ltr"/><Field label="اسم المستخدم" value={captain.username} onChange={v=>setCaptain({...captain,username:v})} dir="ltr"/><Field label="كلمة مرور جديدة — اختياري" value={password} onChange={setPassword} dir="ltr" type="password" className="sm:col-span-2"/><button className="btn-primary mt-2 sm:col-span-2"><Save className="size-4"/>حفظ التعديل</button></form>}
function PromoForm({form,setForm,submit}:{form:{companyName:string;code:string;discountPercent:number;maxUses:string;startsAt:string;expiresAt:string};setForm:(v:{companyName:string;code:string;discountPercent:number;maxUses:string;startsAt:string;expiresAt:string})=>void;submit:(e:FormEvent)=>void}){return <form onSubmit={submit} className="grid gap-3 sm:grid-cols-2"><Field label="اسم الشركة" value={form.companyName} onChange={v=>setForm({...form,companyName:v})}/><Field label="رمز الخصم" value={form.code} onChange={v=>setForm({...form,code:v.toUpperCase().replace(/\s/g,"")})} dir="ltr"/><PercentControl value={form.discountPercent} onChange={v=>setForm({...form,discountPercent:v})}/><Field label="حد الاستخدام — اختياري" value={form.maxUses} onChange={v=>setForm({...form,maxUses:v})} dir="ltr" type="number"/><Field label="يبدأ من" value={form.startsAt} onChange={v=>setForm({...form,startsAt:v})} dir="ltr" type="datetime-local"/><Field label="ينتهي في" value={form.expiresAt} onChange={v=>setForm({...form,expiresAt:v})} dir="ltr" type="datetime-local"/><button className="btn-primary mt-2 sm:col-span-2"><Check className="size-4"/>إنشاء الرمز</button></form>}
function EditPromoForm({promo,setPromo,submit}:{promo:Promo;setPromo:(v:Promo)=>void;submit:(e:FormEvent)=>void}){return <form onSubmit={submit} className="grid gap-3 sm:grid-cols-2"><Field label="اسم الشركة" value={promo.company_name} onChange={v=>setPromo({...promo,company_name:v})}/><Field label="رمز الخصم" value={promo.code} onChange={v=>setPromo({...promo,code:v.toUpperCase().replace(/\s/g,"")})} dir="ltr"/><PercentControl value={promo.discount_percent} onChange={v=>setPromo({...promo,discount_percent:v})}/><Field label="حد الاستخدام" value={promo.max_uses===null?"":String(promo.max_uses)} onChange={v=>setPromo({...promo,max_uses:v?Number(v):null})} dir="ltr" type="number"/><Field label="يبدأ من" value={inputDate(promo.starts_at)} onChange={v=>setPromo({...promo,starts_at:v||null})} dir="ltr" type="datetime-local"/><Field label="ينتهي في" value={inputDate(promo.expires_at)} onChange={v=>setPromo({...promo,expires_at:v||null})} dir="ltr" type="datetime-local"/><button className="btn-primary mt-2 sm:col-span-2"><Save className="size-4"/>حفظ التعديل</button></form>}

function Modal({title,subtitle,onClose,children}:{title:string;subtitle:string;onClose:()=>void;children:ReactNode}){return <div className="fixed inset-0 z-[75] flex items-end justify-center bg-black/40 p-0 sm:items-center sm:p-4" onClick={onClose}><div onClick={e=>e.stopPropagation()} className="w-full max-w-2xl rounded-t-[26px] bg-white p-5 shadow-2xl sm:rounded-[26px]"><div className="mb-5 flex items-start justify-between"><button onClick={onClose} className="icon-btn"><X className="size-4"/></button><div className="text-right"><h2 className="text-xl font-bold">{title}</h2><p className="mt-1 text-xs text-slate-400">{subtitle}</p></div></div>{children}</div></div>}
function Panel({title,subtitle,action,children}:{title:string;subtitle?:string;action?:ReactNode;children:ReactNode}){return <section className="rounded-[22px] border border-slate-200 bg-white shadow-[0_5px_18px_rgba(20,46,62,.035)]"><div className="flex items-start justify-between gap-3 border-b border-slate-100 px-5 py-4">{action||<span/>}<div className="text-right"><h3 className="font-bold">{title}</h3>{subtitle&&<p className="mt-1 text-[10px] text-slate-400">{subtitle}</p>}</div></div><div className="p-4 lg:p-5">{children}</div></section>}
function PageIntro({eyebrow,title,description,actions}:{eyebrow:string;title:string;description:string;actions?:ReactNode}){return <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div>{actions}</div><div className="text-right"><div className="text-[10px] font-bold tracking-[.16em] text-[#2a7188]">{eyebrow}</div><h2 className="mt-2 text-2xl font-bold lg:text-3xl">{title}</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-400">{description}</p></div></div>}
function MetricCard({title,value,sub,icon,trend,danger=false,small=false}:{title:string;value:string|number;sub:string;icon:ReactNode;trend?:string;danger?:boolean;small?:boolean}){return <div className={`rounded-[20px] border bg-white p-4 shadow-[0_5px_18px_rgba(20,46,62,.03)] ${danger?"border-red-100":"border-slate-200"}`}><div className="flex items-start justify-between"><div className={`grid size-10 place-items-center rounded-xl ${danger?"bg-red-50 text-red-600":"bg-[#eaf2f5] text-[#2a7188]"}`}>{icon}</div><div className="text-right"><div className="text-[10px] font-medium text-slate-400">{title}</div><div className={`mt-2 font-bold tracking-tight ${small?"text-lg":"text-2xl"}`}>{value}</div></div></div><div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3 text-[9px]"><span className={danger?"font-semibold text-red-500":"text-slate-400"}>{trend||"محدث الآن"}</span><span className="text-slate-400">{sub}</span></div></div>}
function HeroMini({label,value}:{label:string;value:string|number}){return <div className="rounded-2xl border border-white/10 bg-white/[.055] p-3 text-center"><div className="text-xl font-semibold text-[#e2be80]">{value}</div><div className="mt-1 text-[9px] text-white/40">{label}</div></div>}
function HealthRow({label,value,state}:{label:string;value:string|number;state:"good"|"warn"|"bad"|"neutral"}){const cls=state==="good"?"bg-emerald-400":state==="warn"?"bg-amber-400":state==="bad"?"bg-red-400":"bg-slate-300";return <div className="flex items-center justify-between rounded-xl bg-[#f8fafb] px-3 py-3"><div className="flex items-center gap-2"><span className={`size-2 rounded-full ${cls}`}/><span className="font-semibold text-sm">{value}</span></div><span className="text-xs text-slate-500">{label}</span></div>}
function QuickAction({icon,label,onClick,href}:{icon:ReactNode;label:string;onClick?:()=>void;href?:string}){const cls="flex items-center justify-end gap-2 rounded-xl border border-slate-200 bg-white px-3 py-3 text-xs font-medium hover:border-[#b9d3dc] hover:bg-[#f8fbfc]";return href?<a href={href} className={cls}><span>{label}</span><span className="text-[#2a7188] [&>svg]:size-4">{icon}</span></a>:<button onClick={onClick} className={cls}><span>{label}</span><span className="text-[#2a7188] [&>svg]:size-4">{icon}</span></button>}
function RankPanel({title,rows}:{title:string;rows:{name:string;value:string;sub:string}[]}){return <Panel title={title} subtitle="حسب البيانات الحالية"><div className="space-y-2">{rows.map((r,i)=><div key={`${r.name}-${i}`} className="flex items-center gap-3 rounded-xl bg-[#f8fafb] p-3"><div className="grid size-8 place-items-center rounded-lg bg-white text-xs font-bold text-[#2a7188] shadow-sm">{i+1}</div><div className="min-w-0 flex-1 text-right"><div className="truncate text-sm font-semibold">{r.name}</div><div className="mt-1 text-[9px] text-slate-400">{r.sub}</div></div><div className="text-xs font-bold">{r.value}</div></div>)}{!rows.length&&<Empty text="ماكو بيانات كافية"/>}</div></Panel>}
function SettingRow({icon,title,description,control}:{icon:ReactNode;title:string;description:string;control:ReactNode}){return <div className="flex items-center gap-4 border-b border-slate-100 py-4 last:border-0"><div>{control}</div><div className="flex flex-1 items-center justify-end gap-3"><div className="text-right"><div className="text-sm font-semibold">{title}</div><div className="mt-1 text-[10px] text-slate-400">{description}</div></div><div className="grid size-9 place-items-center rounded-xl bg-[#eaf2f5] text-[#2a7188] [&>svg]:size-4">{icon}</div></div></div>}
function LinkRow({href,title,sub,icon}:{href:string;title:string;sub:string;icon:ReactNode}){return <a href={href} className="flex items-center justify-between border-b border-slate-100 py-4 last:border-0"><ChevronLeft className="size-4 text-slate-300"/><div className="flex items-center gap-3"><div className="text-right"><div className="text-sm font-semibold">{title}</div><div className="mt-1 text-[10px] text-slate-400">{sub}</div></div><div className="grid size-9 place-items-center rounded-xl bg-[#eaf2f5] text-[#2a7188] [&>svg]:size-4">{icon}</div></div></a>}
function SidebarButton({active,icon,label,badge,onClick}:{active:boolean;icon:ReactNode;label:string;badge?:number;onClick:()=>void}){return <button onClick={onClick} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-right text-sm transition ${active?"bg-[#d6ad68] text-[#12384d] shadow-lg shadow-black/10":"text-white/60 hover:bg-white/[.06] hover:text-white"}`}><span className="relative grid size-8 place-items-center [&>svg]:size-4">{icon}{badge&&badge>0?<span className="absolute -left-1 -top-1 min-w-4 rounded-full bg-red-500 px-1 text-center text-[8px] leading-4 text-white">{badge}</span>:null}</span><span className="flex-1">{label}</span>{active&&<ChevronLeft className="size-3 opacity-50"/>}</button>}
function MobileNav({active,icon,label,badge,onClick}:{active:boolean;icon:ReactNode;label:string;badge?:number;onClick:()=>void}){return <button onClick={onClick} className={`relative flex flex-col items-center gap-1 py-1 text-[9px] ${active?"text-[#123f58]":"text-slate-400"}`}><span className={`grid size-8 place-items-center rounded-xl [&>svg]:size-4 ${active?"bg-[#eaf2f5]":""}`}>{icon}</span>{label}{badge&&badge>0?<span className="absolute right-[22%] top-0 min-w-4 rounded-full bg-red-500 px-1 text-[8px] leading-4 text-white">{badge}</span>:null}</button>}
function SourceBadge({source}:{source:"customer"|"captain"}){return <span className={`inline-flex rounded-full px-2.5 py-1 text-[9px] font-semibold ${source==="captain"?"bg-[#e6f1f5] text-[#2a7188]":"bg-slate-100 text-slate-600"}`}>{source==="captain"?"كابتن":"زبون"}</span>}
function StatusBadge({status}:{status:string}){const s=statusMap[status]||statusMap.new;return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[9px] font-semibold ${s.badge}`}><span className={`size-1.5 rounded-full ${s.dot}`}/>{s.label}</span>}
function PriorityBadge({p}:{p:Priority}){const x=priorityMap[p]||priorityMap.normal;return <span className={`rounded-full px-2.5 py-1 text-[9px] font-semibold ${x.badge}`}>{x.label}</span>}
function Detail({label,value,icon}:{label:string;value:string;icon:ReactNode}){return <div className="rounded-xl bg-[#f7f9fa] p-3"><div className="flex items-center justify-end gap-2 text-[9px] text-slate-400"><span>{label}</span><span className="[&>svg]:size-3.5">{icon}</span></div><div className="mt-2 break-words text-right text-sm font-semibold">{value}</div></div>}
function SectionHead({title}:{title:string}){return <div className="mb-2 text-xs font-semibold text-slate-500">{title}</div>}
function Mini({label,value}:{label:string;value:string|number}){return <div className="rounded-xl bg-[#f7f9fa] px-2 py-2 text-center"><div className="truncate text-xs font-bold">{value}</div><div className="mt-1 text-[8px] text-slate-400">{label}</div></div>}
function Select({value,onChange,options}:{value:string;onChange:(v:string)=>void;options:string[][]}){return <select value={value} onChange={e=>onChange(e.target.value)} className="h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-xs outline-none focus:border-[#2a7188]">{options.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select>}
function Field({label,value,onChange,dir="rtl",type="text",className=""}:{label:string;value:string;onChange:(v:string)=>void;dir?:"rtl"|"ltr";type?:string;className?:string}){return <label className={className}><span className="label">{label}</span><input dir={dir} type={type} value={value} onChange={e=>onChange(e.target.value)} className="field mt-1" required={type!=="datetime-local"}/></label>}
function PercentControl({value,onChange}:{value:number;onChange:(v:number)=>void}){return <label><span className="label">نسبة الخصم</span><div className="mt-1 flex h-11 items-center rounded-xl border border-slate-200 bg-white p-1"><button type="button" onClick={()=>onChange(Math.max(1,value-1))} className="grid size-9 place-items-center rounded-lg bg-slate-100"><Minus className="size-4"/></button><div className="flex-1 text-center font-bold">{value}%</div><button type="button" onClick={()=>onChange(Math.min(100,value+1))} className="grid size-9 place-items-center rounded-lg bg-[#10394e] text-white"><Plus className="size-4"/></button></div></label>}
function Empty({text}:{text:string}){return <div className="rounded-xl border border-dashed border-slate-200 bg-[#fafbfc] px-4 py-8 text-center text-xs text-slate-400">{text}</div>}
function Th({children}:{children:ReactNode}){return <th className="px-3 py-3 font-medium">{children}</th>}
function Td({children,className=""}:{children:ReactNode;className?:string}){return <td className={`px-3 py-3 text-xs ${className}`}>{children}</td>}
function activityLabel(a:string){return ({status:"تغيير حالة الطلب",priority:"تغيير الأولوية",note:"تعديل الملاحظة الداخلية",archive:"أرشفة الطلب",restore:"إرجاع الطلب من الأرشيف"} as Record<string,string>)[a]||a}
